package org.jfree.data;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;
import org.jfree.data.exceptions.UnknownKeyException;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.fail;

public class KeyedObjects2D_getObject_TriageGen1Test {

    private KeyedObjects2D dataset;
    private final String ROW_KEY_1 = "Row1";
    private final String ROW_KEY_2 = "Row2";
    private final String COL_KEY_1 = "Col1";
    private final String COL_KEY_2 = "Col2";
    private final Object TEST_VALUE = "TestData";

    @Before
    public void setUp() {
        dataset = new KeyedObjects2D();
    }

    @Test
    public void testGetObject_NullRowKey_ThrowsIllegalArgumentException() {
        try {
            dataset.getObject(null, COL_KEY_1);
            fail("Expected IllegalArgumentException for null rowKey");
        } catch (IllegalArgumentException e) {
            assertEquals("Null 'rowKey' argument.", e.getMessage());
        }
    }

    @Test
    public void testGetObject_NullColumnKey_ThrowsIllegalArgumentException() {
        try {
            dataset.getObject(ROW_KEY_1, null);
            fail("Expected IllegalArgumentException for null columnKey");
        } catch (IllegalArgumentException e) {
            assertEquals("Null 'columnKey' argument.", e.getMessage());
        }
    }

    @Test
    public void testGetObject_UnknownRowKey_ThrowsUnknownKeyException() {
        // Note: The code checks (row < 1). This implies index 0 is treated as unknown 
        // or invalid in this specific logic, which is unusual but must be tested for coverage.
        dataset.addObject(TEST_VALUE, "ValidKeyAtZero", COL_KEY_1);

        try {
            dataset.getObject("UnknownKey", COL_KEY_1);
            fail("Expected UnknownKeyException for unknown rowKey");
        } catch (UnknownKeyException e) {
            assertEquals("Row key (UnknownKey) not recognised.", e.getMessage());
        }
    }

    @Test
    public void testGetObject_UnknownColumnKey_ThrowsUnknownKeyException() {
        // We need to ensure row index is >= 1 to pass the first check
        // Since addObject adds to rowKeys, we add a key and then try to access a non-existent column
        dataset.addObject(TEST_VALUE, ROW_KEY_1, COL_KEY_1);

        // Note: If row index is 0, it fails the row check first. 
        // To trigger column check, we need the row index to be >= 1.
        // We can simulate this by adding a second row.
        dataset.addObject(TEST_VALUE, "RowToMakeIndex1", COL_KEY_1);

        try {
            dataset.getObject("RowToMakeIndex1", "UnknownCol");
            fail("Expected UnknownKeyException for unknown columnKey");
        } catch (UnknownKeyException e) {
            assertEquals("Column key (UnknownCol) not recognised.", e.getMessage());
        }
    }

    @Test
    public void testGetObject_Success() {
        // We need row index >= 1. 
        // First row (index 0) - will fail row < 1 check.
        // Second row (index 1) - will pass.
        dataset.addObject("First", "Row0", COL_KEY_1);
        dataset.addObject(TEST_VALUE, "Row1", COL_KEY_1);

        Object result = dataset.getObject("Row1", COL_KEY_1);
        assertEquals(TEST_VALUE, result);
    }

    @Test
    public void testGetObject_ColumnKeyNotFoundInRow_ReturnsNull() {
        // Row index >= 1
        dataset.addObject("First", "Row0", COL_KEY_1);
        dataset.addObject(TEST_VALUE, "Row1", COL_KEY_1);

        // Add a different column to the dataset so the columnKey is recognized globally
        dataset.addObject(TEST_VALUE, "Row1", COL_KEY_2);

        // Request COL_KEY_2 from Row1, but if we had a way to make it exist in columnKeys 
        // but not in that specific row's KeyedObjects.
        // Since addObject adds to columnKeys, we add COL_KEY_2 to the dataset.
        // Then we check if Row1 has COL_KEY_2. 
        // In the setup above, Row1 DOES have COL_KEY_2.
        // Let's create a scenario where COL_KEY_2 is in the dataset but NOT in Row1.

        dataset.addObject("Other", "Row2", COL_KEY_2);
        // Now:
        // Row0: [Col1]
        // Row1: [Col1, Col2]
        // Row2: [Col2]

        // To test the 'else' branch (index < 0), we need a columnKey that exists in dataset.getColumnKeys()
        // but rowData.getIndex(columnKey) returns < 0.

        // Let's clear and be precise:
        dataset = new KeyedObjects2D();
        dataset.addObject("Val", "Row0", COL_KEY_1); // index 0
        dataset.addObject("Val", "Row1", COL_KEY_1); // index 1
        dataset.addObject("Val", "Row2", COL_KEY_2); // index 2 (adds COL_KEY_2 to columnKeys)

        // Now call getObject for Row1, Col2. 
        // Row1 only has COL_KEY_1.
        Object result = dataset.getObject("Row1", COL_KEY_2);
        assertNull(result);
    }
}
